const received = $input.first().json.body;
if (!Array.isArray(received)) {
  throw new Error('Expected an array of profiles from Apify.');
}
const rows = [];
const seen = new Set();
let missingContact = 0;
let duplicateProfiles = 0;
const normalize = value => String(value ?? '').trim().toLowerCase();

for (const profile of received) {
  const email = normalize(profile?.primaryEmail);
  if (!email || !normalize(profile?.emailSource)) {
    missingContact++;
    continue;
  }
  const identifiers = [];
  if (profile.professionalId) identifiers.push('id:' + String(profile.professionalId).trim());
  if (profile.profileUrl) identifiers.push('url:' + String(profile.profileUrl).trim().replace(/\/+$/, ''));
  if (identifiers.length === 0 && normalize(profile.businessName)) {
    identifiers.push(JSON.stringify([normalize(profile.businessName), normalize(profile.city), normalize(profile.state), email]));
  }
  if (identifiers.some(key => seen.has(key))) {
    duplicateProfiles++;
    continue;
  }
  for (const key of identifiers) seen.add(key);
  rows.push(profile);
}
return [{json: {rows, receivedProfiles: received.length, missingContact, duplicateProfiles}}];

const {rows, receivedProfiles, missingContact, duplicateProfiles} = $input.first().json;
const columns = ["professionalId", "businessName", "category", "city", "state", "primaryEmail", "emailSource", "contactPageUrl", "websiteUrl", "profileUrl"];
function csvCell(value) {
  let text = String(value ?? '');
  if (/^[\s\uFEFF]*[=+@-]/.test(text) || /^[\t\r\n]/.test(text)) text = "'" + text;
  return '"' + text.replace(/"/g, '""') + '"';
}
const lines = [columns.join(','), ...rows.map(row => columns.map(key => csvCell(row[key])).join(','))];
const content = '\uFEFF' + lines.join('\r\n') + '\r\n';
return [{json: {profiles: rows.length, receivedProfiles, missingContact, duplicateProfiles}, binary: {data: {
  data: Buffer.from(content, 'utf8').toString('base64'),
  mimeType: 'text/csv', fileExtension: 'csv', fileName: 'houzz-contractors.csv'
}}}];
